<script setup lang="ts">import { inject, ref, type Ref } from "vue"; import { adjustStock, type Item } from "../../api"; const item = inject<Ref<Item | null>>("inventoryItem"); const quantity = ref(0); const error = ref(""); async function adjust() { if (!item?.value || !quantity.value) return; try { item.value = await adjustStock(item.value.id, quantity.value); quantity.value = 0; } catch (reason) { error.value = (reason as Error).message; } }</script><template><section v-if="item" class="detail-tab"><h2>Catalogo y stock</h2><dl><dt>SKU</dt><dd>{{ item.sku }}</dd><dt>Descripcion</dt><dd>{{ item.description || "Sin descripcion" }}</dd><dt>Stock minimo</dt><dd>{{ item.minimumStock }} {{ item.unit }}</dd></dl><form class="inline-form" @submit.prevent="adjust"><label>Ajuste de stock<input v-model.number="quantity" type="number" /></label><button>Ajustar</button></form><p v-if="error" class="feedback error">{{ error }}</p></section></template>